--
-- Name: claim_sourcing_continuation(uuid, uuid, uuid, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.claim_sourcing_continuation(p_task_id uuid, p_workspace_id uuid, p_claim_id uuid, p_lease_seconds integer DEFAULT 300) RETURNS TABLE(claimed boolean, reason text, task_id uuid, checkpoint_version integer, held_by uuid, held_until timestamp with time zone)
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_row public.tasks%rowtype;
  v_terminal text;
begin
  select * into v_row
    from public.tasks
   where id = p_task_id
     for update;

  if not found then
    return query select false, 'task_not_found'::text, p_task_id, null::integer, null::uuid, null::timestamptz;
    return;
  end if;

  if v_row.workspace_id is distinct from p_workspace_id then
    return query select false, 'workspace_mismatch'::text, p_task_id, null::integer, null::uuid, null::timestamptz;
    return;
  end if;

  if v_row.result -> 'company_first_state' is null then
    return query select false, 'no_checkpoint'::text, p_task_id, null::integer, null::uuid, null::timestamptz;
    return;
  end if;

  v_terminal := coalesce(
    v_row.result ->> 'terminal_status',
    v_row.result -> 'company_first_state' ->> 'terminal_status',
    v_row.result -> 'company_first' ->> 'status'
  );
  if v_terminal is not null and v_terminal <> 'continuation_required' then
    return query select false, 'already_terminal'::text, p_task_id, v_row.checkpoint_version, null::uuid, null::timestamptz;
    return;
  end if;

  if v_row.status in ('complete', 'failed', 'skipped') and v_terminal is distinct from 'continuation_required' then
    return query select false, 'already_terminal'::text, p_task_id, v_row.checkpoint_version, null::uuid, null::timestamptz;
    return;
  end if;

  if v_row.status is distinct from 'ready'
     and v_row.status not in ('partial', 'running', 'complete') then
    return query select false, 'not_resumable_state'::text, p_task_id, v_row.checkpoint_version, null::uuid, null::timestamptz;
    return;
  end if;

  if v_row.continuation_claim_id is not null
     and v_row.continuation_claim_expires_at is not null
     and v_row.continuation_claim_expires_at > now() then
    return query select false, 'already_claimed'::text, p_task_id,
                        v_row.checkpoint_version, v_row.continuation_claim_id, v_row.continuation_claim_expires_at;
    return;
  end if;

  update public.tasks
     set continuation_claim_id         = p_claim_id,
         continuation_claimed_at       = now(),
         continuation_claim_expires_at = now() + make_interval(secs => greatest(p_lease_seconds, 30)),
         checkpoint_version            = public.tasks.checkpoint_version + 1,
         status                        = 'running',
         updated_at                    = now(),
         result                        = coalesce(public.tasks.result, '{}'::jsonb) || jsonb_build_object(
                                           'continuation_claim',
                                           jsonb_build_object(
                                             'claim_id', p_claim_id,
                                             'claimed_at', now(),
                                             'expires_at', now() + make_interval(secs => greatest(p_lease_seconds, 30))
                                           )
                                         )
   where id = p_task_id;

  return query select true, 'claimed'::text, p_task_id,
                      v_row.checkpoint_version + 1, p_claim_id,
                      now() + make_interval(secs => greatest(p_lease_seconds, 30));
end;
$$;


ALTER FUNCTION public.claim_sourcing_continuation(p_task_id uuid, p_workspace_id uuid, p_claim_id uuid, p_lease_seconds integer) OWNER TO postgres;

--
-- Name: credits_finalize(uuid, integer, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.credits_finalize(p_transaction_id uuid, p_actual integer, p_status text, p_reason text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_txn    public.credit_transactions%rowtype;
  v_refund integer;
begin
  select * into v_txn from public.credit_transactions
   where id = p_transaction_id for update;
  if not found then
    return jsonb_build_object('ok', false, 'error', 'unknown_transaction');
  end if;

  if v_txn.status <> 'reserved' then
    return jsonb_build_object('ok', true, 'replayed', true,
      'status', v_txn.status, 'actual_credits', v_txn.actual_credits,
      'refunded_credits', v_txn.refunded_credits);
  end if;

  if p_actual is null or p_actual < 0 or p_actual > v_txn.reserved_credits then
    return jsonb_build_object('ok', false, 'error', 'actual_exceeds_reserved',
      'reserved', v_txn.reserved_credits, 'requested', p_actual);
  end if;

  v_refund := v_txn.reserved_credits - p_actual;

  update public.workspace_credit_balances
     set reserved_credits = reserved_credits - v_txn.reserved_credits,
         balance_credits  = balance_credits  + v_refund,
         updated_at = now()
   where workspace_id = v_txn.workspace_id;

  update public.credit_transactions
     set status = p_status, actual_credits = p_actual,
         refunded_credits = v_refund,
         reason = coalesce(p_reason, reason),
         finalized_at = now()
   where id = p_transaction_id;

  return jsonb_build_object('ok', true, 'replayed', false,
    'status', p_status, 'actual_credits', p_actual,
    'refunded_credits', v_refund);
end;
$$;


ALTER FUNCTION public.credits_finalize(p_transaction_id uuid, p_actual integer, p_status text, p_reason text) OWNER TO postgres;

--
-- Name: credits_grant(uuid, integer, text, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.credits_grant(p_workspace uuid, p_amount integer, p_idempotency_key text, p_reason text DEFAULT NULL::text, p_plan_id text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_existing public.credit_transactions%rowtype;
  v_balance  integer;
begin
  if p_amount is null or p_amount <= 0 then
    return jsonb_build_object('ok', false, 'error', 'invalid_amount');
  end if;

  select * into v_existing from public.credit_transactions
   where workspace_id = p_workspace and idempotency_key = p_idempotency_key;
  if found then
    select balance_credits into v_balance
      from public.workspace_credit_balances where workspace_id = p_workspace;
    return jsonb_build_object('ok', true, 'replayed', true,
      'transaction_id', v_existing.id, 'balance_after', coalesce(v_balance, 0));
  end if;

  insert into public.workspace_credit_balances (workspace_id, balance_credits, plan_id)
  values (p_workspace, p_amount, coalesce(p_plan_id, 'free_trial'))
  on conflict (workspace_id) do update
    set balance_credits = public.workspace_credit_balances.balance_credits + p_amount,
        plan_id = coalesce(p_plan_id, public.workspace_credit_balances.plan_id),
        updated_at = now()
  returning balance_credits into v_balance;

  insert into public.credit_transactions(
    workspace_id, idempotency_key, kind, status,
    actual_credits, reason, finalized_at)
  values (p_workspace, p_idempotency_key, 'grant', 'granted',
    p_amount, p_reason, now());

  return jsonb_build_object('ok', true, 'replayed', false,
    'balance_after', coalesce(v_balance, 0));
end;
$$;


ALTER FUNCTION public.credits_grant(p_workspace uuid, p_amount integer, p_idempotency_key text, p_reason text, p_plan_id text) OWNER TO postgres;

--
-- Name: credits_release_stale(interval); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.credits_release_stale(p_older_than interval DEFAULT '00:30:00'::interval) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_txn public.credit_transactions%rowtype;
  v_n   integer := 0;
begin
  for v_txn in
    select * from public.credit_transactions
     where status = 'reserved' and created_at < now() - p_older_than
     for update skip locked
  loop
    perform public.credits_finalize(
      v_txn.id, 0, 'released', 'stale reservation released by reaper');
    v_n := v_n + 1;
  end loop;
  return v_n;
end;
$$;


ALTER FUNCTION public.credits_release_stale(p_older_than interval) OWNER TO postgres;

--
-- Name: credits_reserve(uuid, integer, text, text, uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.credits_reserve(p_workspace uuid, p_amount integer, p_idempotency_key text, p_kind text, p_task_id uuid DEFAULT NULL::uuid, p_company_key text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_existing public.credit_transactions%rowtype;
  v_balance  integer;
  v_txn_id   uuid;
begin
  if p_amount is null or p_amount < 0 then
    return jsonb_build_object('ok', false, 'error', 'invalid_amount');
  end if;
  if p_idempotency_key is null or length(trim(p_idempotency_key)) = 0 then
    return jsonb_build_object('ok', false, 'error', 'missing_idempotency_key');
  end if;

  select * into v_existing from public.credit_transactions
   where workspace_id = p_workspace and idempotency_key = p_idempotency_key;
  if found then
    return jsonb_build_object(
      'ok', true, 'replayed', true,
      'transaction_id', v_existing.id, 'status', v_existing.status,
      'reserved_credits', v_existing.reserved_credits);
  end if;

  if p_amount > 0 then
    update public.workspace_credit_balances
       set balance_credits  = balance_credits  - p_amount,
           reserved_credits = reserved_credits + p_amount,
           updated_at = now()
     where workspace_id = p_workspace
       and balance_credits >= p_amount
    returning balance_credits into v_balance;

    if not found then
      select balance_credits into v_balance
        from public.workspace_credit_balances where workspace_id = p_workspace;
      return jsonb_build_object('ok', false, 'error', 'insufficient_credits',
        'balance', coalesce(v_balance, 0), 'needed', p_amount);
    end if;
  else
    select balance_credits into v_balance
      from public.workspace_credit_balances where workspace_id = p_workspace;
  end if;

  begin
    insert into public.credit_transactions(
      workspace_id, idempotency_key, kind, status,
      estimated_credits, reserved_credits, task_id, company_key)
    values (p_workspace, p_idempotency_key, p_kind, 'reserved',
      p_amount, p_amount, p_task_id, p_company_key)
    returning id into v_txn_id;
  exception when unique_violation then
    if p_amount > 0 then
      update public.workspace_credit_balances
         set balance_credits  = balance_credits  + p_amount,
             reserved_credits = reserved_credits - p_amount,
             updated_at = now()
       where workspace_id = p_workspace;
    end if;
    select * into v_existing from public.credit_transactions
     where workspace_id = p_workspace and idempotency_key = p_idempotency_key;
    return jsonb_build_object('ok', true, 'replayed', true,
      'transaction_id', v_existing.id, 'status', v_existing.status,
      'reserved_credits', v_existing.reserved_credits);
  end;

  return jsonb_build_object('ok', true, 'replayed', false,
    'transaction_id', v_txn_id, 'balance_after', coalesce(v_balance, 0));
end;
$$;


ALTER FUNCTION public.credits_reserve(p_workspace uuid, p_amount integer, p_idempotency_key text, p_kind text, p_task_id uuid, p_company_key text) OWNER TO postgres;

