    'tasks',              (SELECT count(*) FROM public.tasks),
    'activity_feed',      (SELECT count(*) FROM public.activity_feed),
    'handoffs',           (SELECT count(*) FROM public.handoffs),
    'approvals',          (SELECT count(*) FROM public.approvals)
  );
$$;


