--

CREATE FUNCTION public.is_org_member(org_uuid uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT EXISTS (
    SELECT 1
    FROM public.organization_members om
    WHERE om.organization_id = org_uuid
      AND om.user_id = auth.uid()
      AND om.status = 'active'
  );
$$;


ALTER FUNCTION public.is_org_member(org_uuid uuid) OWNER TO postgres;

--
-- Name: is_room_member(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.is_room_member(_user_id uuid, _room_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT EXISTS (
    SELECT 1
    FROM collaboration_room_members
    WHERE user_id = _user_id
      AND room_id = _room_id
  )
$$;


ALTER FUNCTION public.is_room_member(_user_id uuid, _room_id uuid) OWNER TO postgres;

--
-- Name: release_sourcing_continuation(uuid, uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.release_sourcing_continuation(p_task_id uuid, p_workspace_id uuid, p_claim_id uuid, p_row_status text DEFAULT 'ready'::text) RETURNS boolean
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_released integer;
begin
  if p_row_status not in ('pending', 'running', 'ready', 'awaiting_approval', 'complete', 'failed', 'skipped') then
    raise exception 'invalid task row status: %', p_row_status;
  end if;

  update public.tasks
     set continuation_claim_id         = null,
         continuation_claimed_at       = null,
         continuation_claim_expires_at = null,
         status                        = p_row_status,
         updated_at                    = now(),
         result                        = coalesce(public.tasks.result, '{}'::jsonb) - 'continuation_claim'
   where id = p_task_id
     and workspace_id = p_workspace_id
     and continuation_claim_id = p_claim_id;

  get diagnostics v_released = row_count;
  return v_released > 0;
end;
$$;


ALTER FUNCTION public.release_sourcing_continuation(p_task_id uuid, p_workspace_id uuid, p_claim_id uuid, p_row_status text) OWNER TO postgres;

