--
-- Name: validate_agent_tool_assignment(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.validate_agent_tool_assignment() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  tool_capabilities text[];
  secret_tool_id uuid;
BEGIN
  SELECT capability_types INTO tool_capabilities
  FROM public.tools
  WHERE id = NEW.tool_id;

  IF tool_capabilities IS NULL OR NOT (NEW.capability_type = ANY(tool_capabilities)) THEN
    RAISE EXCEPTION 'Capability type % is not supported by tool %', NEW.capability_type, NEW.tool_id
      USING ERRCODE = '23514';
  END IF;

  IF NEW.secret_connection_id IS NOT NULL THEN
    SELECT tool_id INTO secret_tool_id
    FROM public.secret_connections
    WHERE id = NEW.secret_connection_id;

    IF secret_tool_id IS NOT NULL AND secret_tool_id <> NEW.tool_id THEN
      RAISE EXCEPTION 'Secret connection % is not assigned to tool %', NEW.secret_connection_id, NEW.tool_id
        USING ERRCODE = '23514';
    END IF;
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION public.validate_agent_tool_assignment() OWNER TO postgres;

