--
-- Name: lead_evidence; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.lead_evidence (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    workspace_id uuid NOT NULL,
    evidence_kind text NOT NULL,
    contact_id uuid,
    account_id uuid,
    lead_candidate_id uuid,
    provider text,
    actor_key text,
    actor_id text,
    source_url text,
    source_record_id text,
    observed_at timestamp with time zone DEFAULT now() NOT NULL,
    verified_at timestamp with time zone,
    verification_status text DEFAULT 'unverified'::text NOT NULL,
    confidence text,
    normalized_value jsonb DEFAULT '{}'::jsonb NOT NULL,
    dedupe_key text NOT NULL,
    lifecycle_status text DEFAULT 'active'::text NOT NULL,
    sanitized boolean DEFAULT true NOT NULL,
    legacy_signal_id uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT lead_evidence_confidence_valid CHECK (((confidence IS NULL) OR (confidence = ANY (ARRAY['low'::text, 'medium'::text, 'high'::text])))),
    CONSTRAINT lead_evidence_entity_present CHECK (((contact_id IS NOT NULL) OR (account_id IS NOT NULL) OR (lead_candidate_id IS NOT NULL))),
    CONSTRAINT lead_evidence_kind_valid CHECK ((evidence_kind = ANY (ARRAY['person_identity'::text, 'company_identity'::text, 'person_role'::text, 'person_geography'::text, 'company_geography'::text, 'company_fit'::text, 'provider_provenance'::text]))),
    CONSTRAINT lead_evidence_lifecycle_valid CHECK ((lifecycle_status = ANY (ARRAY['active'::text, 'stale'::text, 'expired'::text, 'contradicted'::text, 'superseded'::text, 'dismissed'::text, 'archived'::text, 'retracted'::text]))),
    CONSTRAINT lead_evidence_verification_valid CHECK ((verification_status = ANY (ARRAY['provider_verified'::text, 'self_reported'::text, 'unverified'::text])))
);


ALTER TABLE public.lead_evidence OWNER TO postgres;

--
-- Name: TABLE lead_evidence; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.lead_evidence IS 'Durable identity / company / provenance evidence. Separate from signal_events because identity facts do not expire and freshness is irrelevant to them. Future home for today''s signals.people_profile rows. No raw provider payload; no email/phone columns.';


--
-- Name: COLUMN lead_evidence.observed_at; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.lead_evidence.observed_at IS 'When this evidence was discovered. Identity evidence has no occurred_at because it is durable, not an event.';


--
-- Name: COLUMN lead_evidence.normalized_value; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.lead_evidence.normalized_value IS 'Sanitized normalized evidence ONLY. Raw provider payloads are forbidden.';


--
-- Name: COLUMN lead_evidence.legacy_signal_id; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.lead_evidence.legacy_signal_id IS 'Maps a future backfill back to the originating public.signals row for idempotency and rollback. ON DELETE SET NULL — legacy signals are never cascade-deleted by this table.';


--
-- Name: lead_execution_calls; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.lead_execution_calls (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    workspace_id uuid NOT NULL,
    task_id uuid,
    plan_id uuid,
    execution_owner text,
    planner_owner text,
    stage text NOT NULL,
    capability text,
    reason text NOT NULL,
    provider_id text NOT NULL,
    actor_id text,
    provider_run_id text,
    dataset_id text,
    request_input jsonb,
    logical_call_key text NOT NULL,
    attempt_number integer DEFAULT 1 NOT NULL,
    status text DEFAULT 'started'::text NOT NULL,
    failure_code text,
    failure_message text,
    started_at timestamp with time zone DEFAULT now() NOT NULL,
    finished_at timestamp with time zone,
    duration_ms integer,
    raw_count integer,
    normalized_count integer,
    unique_count integer,
    accepted_count integer,
    rejected_count integer,
    actual_cost_usd numeric(12,6),
    estimated_cost_usd numeric(12,6),
    cost_source text DEFAULT 'unknown'::text NOT NULL,
    next_decision text,
    metadata jsonb,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    planner_adapter text,
    planner_outcome text,
    planner_fallback_reason text,
    record_kind text DEFAULT 'provider_call'::text NOT NULL,
    CONSTRAINT lead_execution_calls_actual_cost_requires_provider CHECK (((actual_cost_usd IS NULL) OR (cost_source = 'provider_reported'::text))),
    CONSTRAINT lead_execution_calls_attempt_positive CHECK ((attempt_number >= 1)),
    CONSTRAINT lead_execution_calls_cost_source_check CHECK ((cost_source = ANY (ARRAY['provider_reported'::text, 'estimated'::text, 'unknown'::text]))),
    CONSTRAINT lead_execution_calls_fallback_needs_reason CHECK (((planner_outcome <> 'deterministic_fallback'::text) OR (planner_fallback_reason IS NOT NULL))),
    CONSTRAINT lead_execution_calls_planner_adapter_check CHECK (((planner_adapter IS NULL) OR (planner_adapter = ANY (ARRAY['gpt'::text, 'claude'::text, 'none'::text])))),
    CONSTRAINT lead_execution_calls_planner_outcome_check CHECK (((planner_outcome IS NULL) OR (planner_outcome = ANY (ARRAY['selected_directly'::text, 'model_validated'::text, 'deterministic_fallback'::text])))),
    CONSTRAINT lead_execution_calls_record_kind_check CHECK ((record_kind = ANY (ARRAY['provider_call'::text, 'stage_result'::text]))),
    CONSTRAINT lead_execution_calls_stage_result_has_no_run CHECK (((record_kind <> 'stage_result'::text) OR ((provider_run_id IS NULL) AND (dataset_id IS NULL)))),
    CONSTRAINT lead_execution_calls_status_check CHECK ((status = ANY (ARRAY['started'::text, 'succeeded'::text, 'failed'::text, 'timed_out'::text, 'reused'::text])))
);


ALTER TABLE public.lead_execution_calls OWNER TO postgres;

--
-- Name: TABLE lead_execution_calls; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.lead_execution_calls IS 'One row per external provider call. Written before the call returns so a failed run is diagnosable from state alone. Observability only: never consulted to decide provider, budget, retry, broadening, quota or qualification.';


--
-- Name: COLUMN lead_execution_calls.raw_count; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.lead_execution_calls.raw_count IS 'NULL means unknown/not measured. 0 means measured as zero. The distinction is load-bearing.';


--
-- Name: COLUMN lead_execution_calls.actual_cost_usd; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.lead_execution_calls.actual_cost_usd IS 'Only ever set when the provider reported a real figure (cost_source = provider_reported). Estimates live in estimated_cost_usd.';


--
-- Name: COLUMN lead_execution_calls.planner_outcome; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.lead_execution_calls.planner_outcome IS 'selected_directly = the deterministic ladder was the intended planner. deterministic_fallback = a model adapter ran and degraded. These are different states and must not share a label.';


--
-- Name: COLUMN lead_execution_calls.record_kind; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.lead_execution_calls.record_kind IS 'provider_call = one external call. stage_result = a task-level funnel outcome no single call can know. Never merge the two when summing.';


