--
-- Name: outreach_channel_performance; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.outreach_channel_performance AS
 SELECT channel,
    count(*) FILTER (WHERE (status = 'sent'::public.activity_status)) AS total_sent,
    count(*) FILTER (WHERE (response_received = true)) AS total_replies,
    count(*) FILTER (WHERE (response_type = 'positive'::text)) AS positive_replies,
    count(*) FILTER (WHERE (response_type = 'negative'::text)) AS negative_replies,
    round((((count(*) FILTER (WHERE (response_received = true)))::numeric / (NULLIF(count(*) FILTER (WHERE (status = 'sent'::public.activity_status)), 0))::numeric) * (100)::numeric), 1) AS reply_rate_pct
   FROM public.outreach_activities
  GROUP BY channel;


ALTER VIEW public.outreach_channel_performance OWNER TO postgres;

