--
-- Name: outreach_dashboard; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.outreach_dashboard AS
 SELECT count(*) AS total_leads,
    count(*) FILTER (WHERE (status = 'not_started'::public.lead_status)) AS not_started,
    count(*) FILTER (WHERE (status = 'in_sequence'::public.lead_status)) AS in_sequence,
    count(*) FILTER (WHERE (status = 'replied'::public.lead_status)) AS replied,
    count(*) FILTER (WHERE (status = 'meeting_booked'::public.lead_status)) AS meetings_booked,
    count(*) FILTER (WHERE (status = 'closed'::public.lead_status)) AS closed,
    count(*) FILTER (WHERE (status = 'dead'::public.lead_status)) AS dead,
    count(*) FILTER (WHERE (closely_connection_status = 'accepted'::text)) AS linkedin_connected,
    count(*) FILTER (WHERE (closely_connection_status = 'pending'::text)) AS linkedin_pending,
    count(*) FILTER (WHERE (created_at > (now() - '7 days'::interval))) AS new_leads_this_week,
    count(*) FILTER (WHERE ((status = 'replied'::public.lead_status) AND (updated_at > (now() - '7 days'::interval)))) AS replies_this_week,
    count(*) FILTER (WHERE ((status = 'meeting_booked'::public.lead_status) AND (updated_at > (now() - '7 days'::interval)))) AS meetings_this_week
   FROM public.outreach_leads;


ALTER VIEW public.outreach_dashboard OWNER TO postgres;

