);


ALTER TABLE public.signal_event_evidence OWNER TO postgres;

--
-- Name: TABLE signal_event_evidence; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.signal_event_evidence IS 'Per-source observations supporting one canonical signal_event. Several providers may evidence the same event; a new observation never rewrites the parent occurred_at. No raw provider payload.';


--
-- Name: COLUMN signal_event_evidence.legacy_signal_id; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.signal_event_evidence.legacy_signal_id IS 'A single legacy signals row may map to BOTH a signal_events row and one signal_event_evidence row (event + the observation that produced it). Uniqueness is therefore per-table, not global, and this column is intentionally non-unique here.';


--
-- Name: signal_events; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.signal_events (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    workspace_id uuid NOT NULL,
    contact_id uuid,
    account_id uuid,
    lead_candidate_id uuid,
    signal_type text NOT NULL,
    signal_category text NOT NULL,
    evidence_category text,
    occurred_at timestamp with time zone NOT NULL,
    observed_at timestamp with time zone DEFAULT now() NOT NULL,
    expires_at timestamp with time zone,
    freshness text,
    confidence text,
    verification_status text DEFAULT 'unverified'::text NOT NULL,
    listing_status text,
    normalized_value jsonb DEFAULT '{}'::jsonb NOT NULL,
    dedupe_key text NOT NULL,
    lifecycle_status text DEFAULT 'active'::text NOT NULL,
    sanitized boolean DEFAULT true NOT NULL,
    provider text,
    actor_key text,
    actor_id text,
    source_url text,
    legacy_signal_id uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT signal_events_category_valid CHECK ((signal_category = ANY (ARRAY['growth'::text, 'gtm'::text, 'product'::text, 'founder_intent'::text, 'risk'::text]))),
    CONSTRAINT signal_events_confidence_valid CHECK (((confidence IS NULL) OR (confidence = ANY (ARRAY['low'::text, 'medium'::text, 'high'::text])))),
    CONSTRAINT signal_events_entity_present CHECK (((contact_id IS NOT NULL) OR (account_id IS NOT NULL) OR (lead_candidate_id IS NOT NULL))),
    CONSTRAINT signal_events_evidence_category_valid CHECK (((evidence_category IS NULL) OR (evidence_category = ANY (ARRAY['job_signal'::text, 'funding_signal'::text, 'launch_signal'::text, 'expansion_signal'::text, 'founder_activity_signal'::text, 'gtm_signal'::text])))),
    CONSTRAINT signal_events_freshness_valid CHECK (((freshness IS NULL) OR (freshness = ANY (ARRAY['strong'::text, 'medium'::text, 'weak_supporting'::text, 'stale'::text])))),
    CONSTRAINT signal_events_lifecycle_valid CHECK ((lifecycle_status = ANY (ARRAY['active'::text, 'stale'::text, 'expired'::text, 'contradicted'::text, 'superseded'::text, 'dismissed'::text, 'archived'::text, 'retracted'::text]))),
    CONSTRAINT signal_events_listing_status_valid CHECK (((listing_status IS NULL) OR (listing_status = ANY (ARRAY['active'::text, 'closed'::text, 'expired'::text, 'unknown'::text])))),
    CONSTRAINT signal_events_type_valid CHECK ((signal_type = ANY (ARRAY['recent_funding'::text, 'employee_growth'::text, 'market_expansion'::text, 'geographic_expansion'::text, 'sales_hiring'::text, 'revops_hiring'::text, 'growth_hiring'::text, 'new_revenue_leader'::text, 'outbound_initiative'::text, 'positioning_change'::text, 'product_launch'::text, 'major_release'::text, 'new_integration'::text, 'category_expansion'::text, 'founder_pipeline_post'::text, 'founder_outbound_post'::text, 'founder_customer_acquisition_post'::text, 'founder_hiring_post'::text, 'founder_problem_statement'::text, 'person_left_company'::text, 'company_outside_icp'::text, 'role_changed'::text, 'company_inactive'::text, 'signal_became_stale'::text]))),
    CONSTRAINT signal_events_verification_valid CHECK ((verification_status = ANY (ARRAY['provider_verified'::text, 'self_reported'::text, 'unverified'::text])))
);


ALTER TABLE public.signal_events OWNER TO postgres;

--
-- Name: TABLE signal_events; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.signal_events IS 'Canonical time-bound opportunity events ("why now?"). Engagement interactions are deliberately excluded — see engagement_events. No raw provider payload; no email/phone columns.';


--
-- Name: COLUMN signal_events.occurred_at; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.signal_events.occurred_at IS 'When the real-world event HAPPENED. This — never observed_at — controls freshness. A round announced months ago but scraped today is stale.';


--
-- Name: COLUMN signal_events.observed_at; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.signal_events.observed_at IS 'When Agentory discovered the event. Audit/provenance only; it must never refresh an old event.';


--
-- Name: COLUMN signal_events.freshness; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.signal_events.freshness IS 'Last computed TimingFreshnessBand. A materialized convenience: occurred_at plus the freshness policy remains authoritative.';


--
-- Name: COLUMN signal_events.dedupe_key; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.signal_events.dedupe_key IS 'Deterministic event identity so the same real-world event found by several providers collapses to one row (unique per workspace).';


--
-- Name: COLUMN signal_events.legacy_signal_id; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.signal_events.legacy_signal_id IS 'Maps a future backfill back to the originating public.signals row. ON DELETE SET NULL — legacy signals are never cascade-deleted.';


