    workspace_id uuid NOT NULL,
    plan_id uuid,
    task_id uuid,
    agent_id uuid,
    tool_name text NOT NULL,
    provider text NOT NULL,
    input_json jsonb,
    output_json jsonb,
    status text DEFAULT 'pending'::text NOT NULL,
    error text,
    started_at timestamp with time zone,
    completed_at timestamp with time zone,
    created_by uuid,
