--
-- Name: tools; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.tools (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    slug text NOT NULL,
    name text NOT NULL,
    provider text NOT NULL,
    capability_types text[] DEFAULT ARRAY[]::text[] NOT NULL,
    supported_actions jsonb DEFAULT '[]'::jsonb NOT NULL,
    config_schema jsonb DEFAULT '{}'::jsonb NOT NULL,
    enabled boolean DEFAULT true NOT NULL,
    metadata jsonb DEFAULT '{}'::jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT tools_capabilities_not_empty CHECK ((array_length(capability_types, 1) IS NOT NULL)),
    CONSTRAINT tools_provider_format CHECK ((provider ~ '^[a-z0-9]+(?:[-_][a-z0-9]+)*$'::text)),
    CONSTRAINT tools_slug_format CHECK ((slug ~ '^[a-z0-9]+(?:[-_][a-z0-9]+)*$'::text))
);


