--
-- Name: INDEX lead_candidates_company_scope_uniq; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON INDEX public.lead_candidates_company_scope_uniq IS 'One account-type lead candidate per (workspace, account) when it anchors no contact and no signal. Makes repeated Mission hiring runs idempotent. Deliberately partial: account_id is not unique across lead_candidates, because a workspace legitimately holds many candidates per account across the person, contact and signal dimensions.';


